def _finalize_responses_stream(
    span: Any,
    chunks: List[Any],
    duration_ms: float,
    ttft_ms: Optional[float],
    *,
    interrupted: bool = False,
) -> None:
    """Finalize a streaming Responses API span (events carry .type / .delta / .response)."""
    text_parts: List[str] = []
    set_media_attributes(span, "neatlogs.llm.output_messages.0", chunks, "output")
    model = None
    usage = None
    error_message: Optional[str] = None
    for ev in chunks:
        ev_type = getattr(ev, "type", "") or ""
        if ev_type == "response.output_text.delta":
            d = getattr(ev, "delta", None)
            if d:
                text_parts.append(d)
        # Detect terminal error events: type may be 'response.error' or 'error'
        if ev_type in ("response.error", "error") or "error" in str(ev_type).lower():
            # Try to extract a human-readable message from the event
            msg = (
                getattr(ev, "message", None)
                or getattr(ev, "error", None)
                or getattr(ev, "code", None)
            )
            if msg is None:
                msg = str(ev)
            error_message = str(msg)
        resp = getattr(ev, "response", None)
        if resp is not None:
            if getattr(resp, "model", None):
                model = resp.model
            if getattr(resp, "usage", None):
                usage = resp.usage
            # A response object with status 'failed' or 'incomplete' also signals error
            resp_status = getattr(resp, "status", None)
            if resp_status in ("failed",) and error_message is None:
                err_obj = getattr(resp, "error", None)
                if err_obj is not None:
                    error_message = str(
                        getattr(err_obj, "message", None) or getattr(err_obj, "code", None) or err_obj
                    )
    if text_parts:
        span.set_attribute("neatlogs.llm.output_messages.0.role", "assistant")
        span.set_attribute("neatlogs.llm.output_messages.0.content", "".join(text_parts)[:10000])
    if model:
        span.set_attribute("neatlogs.llm.model_name", model)
    if usage:
        it = getattr(usage, "input_tokens", None)
        ot_ = getattr(usage, "output_tokens", None)
        if it is not None:
            span.set_attribute("neatlogs.llm.token_count.prompt", it)
        if ot_ is not None:
            span.set_attribute("neatlogs.llm.token_count.completion", ot_)
    span.set_attribute("neatlogs.llm.metrics.duration_ms", round(duration_ms, 3))
    if ttft_ms is not None:
        span.set_attribute("neatlogs.llm.metrics.ttft_ms", round(ttft_ms, 3))
    if error_message is not None:
        span.set_status(StatusCode.ERROR, error_message)
        span.record_exception(RuntimeError(error_message))
    elif interrupted:
        span.set_status(StatusCode.UNSET)
    else:
        span.set_status(StatusCode.OK)
    span.end()
